def remove_nth_from_end(head, n):
    # Lead pointer n steps ahead; when it hits the end, trail sits before the target.
    dummy = ListNode(0, head)
    lead = trail = dummy
    for _ in range(n + 1):
        lead = lead.next
    while lead:
        lead = lead.next
        trail = trail.next
    trail.next = trail.next.next
    return dummy.next

