def has_cycle(head):
    # Floyd's tortoise and hare: the fast pointer laps the slow one inside a cycle.
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False

