def diameter_of_binary_tree(root):
    # Post-order heights; the best path through a node is left height + right height.
    best = 0

    def height(node):
        nonlocal best
        if not node:
            return 0
        left, right = height(node.left), height(node.right)
        best = max(best, left + right)
        return 1 + max(left, right)

    height(root)
    return best

