def lowest_common_ancestor(root, p, q):
    # Walk down until p and q fall on different sides (or one equals the current node).
    node = root
    while node:
        if p.val < node.val and q.val < node.val:
            node = node.left
        elif p.val > node.val and q.val > node.val:
            node = node.right
        else:
            return node
    return None

