def right_side_view(root):
    # DFS visiting right children first; the first node seen at each depth is visible.
    view = []

    def dfs(node, depth):
        if not node:
            return
        if depth == len(view):
            view.append(node.val)
        dfs(node.right, depth + 1)
        dfs(node.left, depth + 1)

    dfs(root, 0)
    return view

