def build_tree_from_traversals(preorder, inorder):
    # The next preorder value is the root; its inorder index splits left and right subtrees.
    index_of = {value: i for i, value in enumerate(inorder)}
    next_root = 0

    def build(lo, hi):
        nonlocal next_root
        if lo > hi:
            return None
        value = preorder[next_root]
        next_root += 1
        node = TreeNode(value)
        mid = index_of[value]
        node.left = build(lo, mid - 1)
        node.right = build(mid + 1, hi)
        return node

    return build(0, len(inorder) - 1)

