class Codec:
    # Preorder traversal with '#' marking empty children.
    def serialize(self, root):
        parts = []

        def dfs(node):
            if not node:
                parts.append('#')
                return
            parts.append(str(node.val))
            dfs(node.left)
            dfs(node.right)

        dfs(root)
        return ','.join(parts)

    def deserialize(self, data):
        tokens = iter(data.split(','))

        def build():
            token = next(tokens)
            if token == '#':
                return None
            node = TreeNode(int(token))
            node.left = build()
            node.right = build()
            return node

        return build()

