class KthLargest:
    # Min-heap holding the k largest values; its root is the kth largest.
    def __init__(self, k, nums):
        self.k = k
        self.heap = []
        for value in nums:
            self.add(value)

    def add(self, val):
        heapq.heappush(self.heap, val)
        if len(self.heap) > self.k:
            heapq.heappop(self.heap)
        return self.heap[0]

