def find_kth_largest(nums, k):
    # Min-heap of the k largest seen so far. O(N log k) time.
    heap = []
    for value in nums:
        heapq.heappush(heap, value)
        if len(heap) > k:
            heapq.heappop(heap)
    return heap[0]

import random

def find_kth_largest(nums, k):
    # Quickselect with a random pivot and three-way partition. O(N) average time.
    target = len(nums) - k
    lo, hi = 0, len(nums) - 1
    nums = list(nums)
    while True:
        pivot = nums[random.randint(lo, hi)]
        lt, i, gt = lo, lo, hi
        while i <= gt:
            if nums[i] < pivot:
                nums[lt], nums[i] = nums[i], nums[lt]
                lt += 1
                i += 1
            elif nums[i] > pivot:
                nums[i], nums[gt] = nums[gt], nums[i]
                gt -= 1
            else:
                i += 1
        if target < lt:
            hi = lt - 1
        elif target > gt:
            lo = gt + 1
        else:
            return pivot

