class MedianFinder:
    # Max-heap for the lower half (negated), min-heap for the upper half.
    def __init__(self):
        self.low = []
        self.high = []

    def add_num(self, num):
        heapq.heappush(self.low, -num)
        heapq.heappush(self.high, -heapq.heappop(self.low))
        if len(self.high) > len(self.low):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def find_median(self):
        if len(self.low) > len(self.high):
            return float(-self.low[0])
        return (-self.low[0] + self.high[0]) / 2

class Trie:
    # Nested dicts; the '$' key marks the end of a word.
    def __init__(self):
        self.root = {}

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node['$'] = True

    def _walk(self, text):
        node = self.root
        for ch in text:
            if ch not in node:
                return None
            node = node[ch]
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and '$' in node

    def starts_with(self, prefix):
        return self._walk(prefix) is not None

def permute(nums):
    # Backtrack by swapping each remaining element into the current position.
    result = []

    def backtrack(first):
        if first == len(nums):
            result.append(nums[:])
            return
        for i in range(first, len(nums)):
            nums[first], nums[i] = nums[i], nums[first]
            backtrack(first + 1)
            nums[first], nums[i] = nums[i], nums[first]

    backtrack(0)
    return result

def exist(board, word):
    # DFS from every cell, temporarily marking visited cells.
    rows, cols = len(board), len(board[0])

    def dfs(r, c, i):
        if i == len(word):
            return True
        if r < 0 or c < 0 or r >= rows or c >= cols or board[r][c] != word[i]:
            return False
        saved = board[r][c]
        board[r][c] = '#'
        found = (dfs(r + 1, c, i + 1) or dfs(r - 1, c, i + 1)
                 or dfs(r, c + 1, i + 1) or dfs(r, c - 1, i + 1))
        board[r][c] = saved
        return found

    return any(dfs(r, c, 0) for r in range(rows) for c in range(cols))

def num_islands(grid):
    # Iterative DFS that sinks each visited island. O(M*N) time.
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '1':
                continue
            count += 1
            stack = [(r, c)]
            grid[r][c] = '0'
            while stack:
                cr, cc = stack.pop()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '1':
                        grid[nr][nc] = '0'
                        stack.append((nr, nc))
    return count

def num_islands(grid):
    # Union-Find over land cells; each union merges two islands into one.
    rows, cols = len(grid), len(grid[0])
    parent = {}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1':
                parent[(r, c)] = (r, c)
                count += 1
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '1':
                continue
            for nr, nc in ((r + 1, c), (r, c + 1)):
                if nr < rows and nc < cols and grid[nr][nc] == '1':
                    a, b = find((r, c)), find((nr, nc))
                    if a != b:
                        parent[a] = b
                        count -= 1
    return count

def max_area_of_island(grid):
    # Recursive flood fill returning the size of each island.
    rows, cols = len(grid), len(grid[0])

    def area(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] != 1:
            return 0
        grid[r][c] = 0
        return 1 + area(r + 1, c) + area(r - 1, c) + area(r, c + 1) + area(r, c - 1)

    return max((area(r, c) for r in range(rows) for c in range(cols)), default=0)

from collections import deque

def oranges_rotting(grid):
    # Multi-source BFS from all initially rotten oranges.
    rows, cols = len(grid), len(grid[0])
    queue = deque()
    fresh = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                queue.append((r, c))
            elif grid[r][c] == 1:
                fresh += 1
    minutes = 0
    while queue and fresh:
        for _ in range(len(queue)):
            r, c = queue.popleft()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                    grid[nr][nc] = 2
                    fresh -= 1
                    queue.append((nr, nc))
        minutes += 1
    return minutes if fresh == 0 else -1

def find_order(num_courses, prerequisites):
    # DFS topological sort with three colors to detect cycles.
    graph = [[] for _ in range(num_courses)]
    for course, prereq in prerequisites:
        graph[prereq].append(course)
    state = [0] * num_courses  # 0 = unvisited, 1 = visiting, 2 = done
    order = []

    def dfs(node):
        if state[node] == 1:
            return False
        if state[node] == 2:
            return True
        state[node] = 1
        for nxt in graph[node]:
            if not dfs(nxt):
                return False
        state[node] = 2
        order.append(node)
        return True

    for course in range(num_courses):
        if not dfs(course):
            return []
    return order[::-1]

from collections import deque

def ladder_length(begin_word, end_word, word_list):
    # BFS over words, generating neighbours by changing one letter at a time.
    words = set(word_list)
    if end_word not in words:
        return 0
    queue = deque([(begin_word, 1)])
    seen = {begin_word}
    while queue:
        word, steps = queue.popleft()
        if word == end_word:
            return steps
        for i in range(len(word)):
            for ch in 'abcdefghijklmnopqrstuvwxyz':
                candidate = word[:i] + ch + word[i + 1:]
                if candidate in words and candidate not in seen:
                    seen.add(candidate)
                    queue.append((candidate, steps + 1))
    return 0

import heapq

def network_delay_time(times, n, k):
    # Dijkstra's algorithm from k; the answer is the largest shortest distance.
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, w in times:
        graph[u].append((v, w))
    dist = {}
    heap = [(0, k)]
    while heap:
        d, node = heapq.heappop(heap)
        if node in dist:
            continue
        dist[node] = d
        for nxt, w in graph[node]:
            if nxt not in dist:
                heapq.heappush(heap, (d + w, nxt))
    return max(dist.values()) if len(dist) == n else -1

def climb_stairs(n):
    # Bottom-up Fibonacci with two rolling variables. O(N) time, O(1) space.
    one, two = 1, 1
    for _ in range(n - 1):
        one, two = one + two, one
    return one

from functools import lru_cache

def climb_stairs(n):
    # Top-down recursion with memoization.
    @lru_cache(maxsize=None)
    def ways(step):
        if step <= 1:
            return 1
        return ways(step - 1) + ways(step - 2)

    return ways(n)

def rob(nums):
    # dp over houses: best is max(skip this house, rob it + best two back).
    prev, curr = 0, 0
    for value in nums:
        prev, curr = curr, max(curr, prev + value)
    return curr

def longest_palindrome(s):
    # Expand around every center (odd and even lengths). O(N^2) time, O(1) space.
    best_start, best_len = 0, 0
    for center in range(len(s)):
        for left, right in ((center, center), (center, center + 1)):
            while left >= 0 and right < len(s) and s[left] == s[right]:
                left -= 1
                right += 1
            if right - left - 1 > best_len:
                best_start, best_len = left + 1, right - left - 1
    return s[best_start:best_start + best_len]

def coin_change(coins, amount):
    # Unbounded knapsack: dp[a] = fewest coins summing to a.
    INF = amount + 1
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for coin in coins:
            if coin <= a and dp[a - coin] + 1 < dp[a]:
                dp[a] = dp[a - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

def word_break(s, word_dict):
    # dp[i] is True when s[:i] can be segmented.
    words = set(word_dict)
    max_len = max(map(len, words), default=0)
    dp = [True] + [False] * len(s)
    for i in range(1, len(s) + 1):
        for j in range(max(0, i - max_len), i):
            if dp[j] and s[j:i] in words:
                dp[i] = True
                break
    return dp[len(s)]

def length_of_lis(nums):
    # Quadratic DP: dp[i] = longest increasing subsequence ending at i. O(N^2) time.
    if not nums:
        return 0
    dp = [1] * len(nums)
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

import bisect

def length_of_lis(nums):
    # Patience sorting: tails[k] is the smallest tail of an increasing run of length k+1. O(N log N).
    tails = []
    for value in nums:
        index = bisect.bisect_left(tails, value)
        if index == len(tails):
            tails.append(value)
        else:
            tails[index] = value
    return len(tails)

def unique_paths(m, n):
    # Rolling 1-D DP: paths to a cell = paths from above + paths from the left.
    row = [1] * n
    for _ in range(1, m):
        for c in range(1, n):
            row[c] += row[c - 1]
    return row[-1]

def longest_common_subsequence(text1, text2):
    # Classic 2-D DP table over prefixes.
    m, n = len(text1), len(text2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

def min_distance(word1, word2):
    # Levenshtein DP keeping only the previous row.
    prev = list(range(len(word2) + 1))
    for i in range(1, len(word1) + 1):
        curr = [i] + [0] * len(word2)
        for j in range(1, len(word2) + 1):
            if word1[i - 1] == word2[j - 1]:
                curr[j] = prev[j - 1]
            else:
                curr[j] = 1 + min(prev[j], curr[j - 1], prev[j - 1])
        prev = curr
    return prev[-1]

def max_sub_array(nums):
    # Divide and conquer: best of left half, right half, or a sum crossing the middle. O(N log N).
    def solve(lo, hi):
        if lo == hi:
            return nums[lo]
        mid = (lo + hi) // 2
        left_best = float('-inf')
        total = 0
        for i in range(mid, lo - 1, -1):
            total += nums[i]
            left_best = max(left_best, total)
        right_best = float('-inf')
        total = 0
        for i in range(mid + 1, hi + 1):
            total += nums[i]
            right_best = max(right_best, total)
        return max(solve(lo, mid), solve(mid + 1, hi), left_best + right_best)

    return solve(0, len(nums) - 1)

def can_jump(nums):
    # Greedy: track the farthest index reachable so far.
    farthest = 0
    for i, jump in enumerate(nums):
        if i > farthest:
            return False
        farthest = max(farthest, i + jump)
    return True

def single_number(nums):
    # XOR cancels out pairs, leaving the unique value.
    result = 0
    for value in nums:
        result ^= value
    return result

def missing_number(nums):
    # Gauss sum of 0..n minus the actual sum.
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)
